const _poly = require("_poly");
module.exports = {
  set_wheels(l, r) {
    if (_poly.sim_get("estop") === true) {
      _poly.sim_set("moving", false);
      _poly.sim_set("left_speed", 0);
      _poly.sim_set("right_speed", 0);
      _poly.sim_set("drive_log:append", "[ESTOP] 急停锁定中，拒绝动力输出");
      return;
    }
    const lv = Math.max(0, Math.min(100, Math.floor(Number(l) || 0)));
    const rv = Math.max(0, Math.min(100, Math.floor(Number(r) || 0)));
    _poly.sim_set("left_speed", lv);
    _poly.sim_set("right_speed", rv);
    _poly.sim_set("moving", lv > 0 || rv > 0);
    _poly.sim_set("drive_log:append", `wheels(L=${lv}%, R=${rv}%)`);
  },
  stop() {
    _poly.sim_set("left_speed", 0);
    _poly.sim_set("right_speed", 0);
    _poly.sim_set("moving", false);
    _poly.sim_set("drive_log:append", "[STOP] 双轮动力已归零");
  },
  battery() {
    const v = Number(_poly.sim_get("battery"));
    return Number.isFinite(v) ? Math.trunc(v) : 86;
  },
  is_estop() {
    return _poly.sim_get("estop") === true;
  },
};
